import django.core.validators
import re

from django.db import migrations, models


def remplir_noms_utilisateur(apps, schema_editor):
    """Les comptes existants n'ont pas de nom d'utilisateur : on leur en donne un, tiré de la partie de leur adresse
    e-mail avant l'arobase (nettoyée, unique, 30 caractères au plus). Ils pourront le changer dans l'admin."""
    Utilisateur = apps.get_model('ticketing', 'Utilisateur')
    pris = set(Utilisateur.objects.exclude(username__isnull=True).values_list('username', flat=True))
    pris = {nom.lower() for nom in pris}
    for utilisateur in Utilisateur.objects.filter(username__isnull=True).order_by('pk'):
        base = re.sub(r'[^\w.-]', '', utilisateur.email.split('@')[0])[:30] or 'membre'
        if len(base) < 3:
            base = (base + 'membre')[:30]
        nom, n = base, 1
        while nom.lower() in pris:
            n += 1
            suffixe = str(n)
            nom = base[:30 - len(suffixe)] + suffixe
        pris.add(nom.lower())
        utilisateur.username = nom
        utilisateur.save(update_fields=['username'])


